/* Pixel-style counter – cohesive palette: dark blue bg, light card, accent pink, dark text */
:root {
  --bg: #1a1a2e;
  --card: #e9e9f0;
  --accent: #e94560;
  --text: #16213e;
  --shadow: #0f0f1a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  padding: 1rem;
}

.card {
  background: var(--card);
  padding: 2rem 1.5rem;
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--shadow);
  text-align: center;
  width: 100%;
  max-width: 400px;
  border: 4px solid var(--text);
}

h1 {
  font-size: 1.8rem;
  color: var(--text);
  margin-bottom: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  border-bottom: 4px solid var(--accent);
  display: inline-block;
  padding-bottom: 0.25rem;
}

.count {
  font-size: 5rem;
  font-weight: bold;
  color: var(--text);
  margin: 1rem 0 2rem;
  line-height: 1;
  min-height: 6rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  border: 4px solid var(--text);
  box-shadow: inset 4px 4px 0 rgba(0,0,0,0.1);
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: bold;
  padding: 0.75rem 1.25rem;
  background: var(--text);
  color: var(--card);
  border: 4px solid var(--text);
  cursor: pointer;
  transition: background 0.1s, color 0.1s, transform 0.05s;
  box-shadow: 4px 4px 0 var(--shadow);
  min-width: 80px;
}

button:hover {
  background: var(--accent);
  color: var(--text);
  border-color: var(--accent);
}

button:focus-visible {
  outline: 4px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

/* Responsive tweaks */
@media (max-width: 400px) {
  .count { font-size: 3.5rem; min-height: 4rem; }
  button { font-size: 1rem; padding: 0.6rem 1rem; min-width: 60px; }
  .card { padding: 1.5rem 1rem; }
}

// Pixel-style counter – no dependencies, no storage.
(function() {
  'use strict';

  let count = 0;
  const countEl = document.getElementById('count');
  const increaseBtn = document.getElementById('increase');
  const decreaseBtn = document.getElementById('decrease');
  const resetBtn = document.getElementById('reset');

  function updateDisplay() {
    countEl.textContent = count;
  }

  function changeBy(delta) {
    count += delta;
    updateDisplay();
  }

  function reset() {
    count = 0;
    updateDisplay();
  }

  increaseBtn.addEventListener('click', function() { changeBy(1); });
  decreaseBtn.addEventListener('click', function() { changeBy(-1); });
  resetBtn.addEventListener('click', reset);

  // Keyboard shortcuts: + and - keys (with or without shift), r for reset
  document.addEventListener('keydown', function(e) {
    // Ignore if focus is on a button to avoid double-trigger (space/enter)
    if (e.target.tagName === 'BUTTON') return;

    switch (e.key) {
      case '+':
      case '=': // common on some layouts
        e.preventDefault();
        changeBy(1);
        break;
      case '-':
      case '_':
        e.preventDefault();
        changeBy(-1);
        break;
      case 'r':
      case 'R':
        e.preventDefault();
        reset();
        break;
    }
  });

  updateDisplay();
})();
